<script>
(function(){
    function escapeHtml(t){ if(!t) return ''; var d = document.createElement('div'); d.textContent = t; return d.innerHTML; }

    function updateHeight(){ 
        setTimeout(function(){ 
            var h = document.body.scrollHeight; 
            if(window.parent && window.parent !== window) {
                window.parent.postMessage({type:'resizeIframe', height:h}, '*'); 
            }
        }, 50); 
    }

    function extractRawQuest(){
        var el = document.getElementById('questRawData');
        return el ? (el.value || el.textContent || '').trim() : '';
    }

    function parseQuestContent(raw) {
        var result = {
            title: '',
            type: '委托',
            difficulty: '',
            difficultyStars: 0,
            reward: '',
            detail: '',
            publisher: ''
        };

        if(!raw || !raw.trim()) return result;

        // 解析标题 - 支持【委托：xxx】或【xxx】格式
        var titleMatch = raw.match(/【(?:委托|任务|主线|支线|日常|紧急)?[：:]?\s*([^】]+)】/);
        if(titleMatch) {
            result.title = titleMatch[2] ? titleMatch[2].trim() : titleMatch[1].trim();
            // 检测任务类型
            var typePrefix = titleMatch[1];
            if(typePrefix) {
                if(typePrefix.indexOf('主线') !== -1) result.type = '主线';
                else if(typePrefix.indexOf('支线') !== -1) result.type = '支线';
                else if(typePrefix.indexOf('日常') !== -1) result.type = '日常';
                else if(typePrefix.indexOf('紧急') !== -1) result.type = '紧急';
                else if(typePrefix.indexOf('委托') !== -1) result.type = '委托';
            }
        }

        // 备用标题匹配
        if(!result.title) {
            var altTitleMatch = raw.match(/\*\*【[^】]+】\**/);
            if(altTitleMatch) {
                var inner = altTitleMatch[0].replace(/\*\*/g, '').replace(/【|】/g, '');
                result.title = inner.replace(/^(委托|任务|主线|支线|日常|紧急)[：:]?\s*/, '');
            }
        }

        // 解析难度
        var diffMatch = raw.match(/\*\*难度[：:]\*\*\s*([^\n]+)/i);
        if(diffMatch) {
            result.difficulty = diffMatch[1].trim();
            // 计算星星数量
            var stars = (result.difficulty.match(/★/g) || []).length;
            result.difficultyStars = stars;
        }

        // 解析报酬
        var rewardMatch = raw.match(/\*\*报酬[：:]\*\*\s*([^\n]+)/i);
        if(rewardMatch) result.reward = rewardMatch[1].trim();

        // 解析详情
        var detailMatch = raw.match(/\*\*详情[：:]\*\*\s*([^\n]+(?:\n(?!\s*(?:\*\s*)?\*\*)[^\n]*)*)/i);
        if(detailMatch) result.detail = detailMatch[1].trim();

        // 解析发布者
        var pubMatch = raw.match(/\*\*发布者[：:]\*\*\s*([^\n]+)/i);
        if(pubMatch) result.publisher = pubMatch[1].trim();

        return result;
    }

    function getQuestIcon(type) {
        var icons = {
            '主线': '⚔️',
            '支线': '📋',
            '日常': '🔄',
            '紧急': '🔥',
            '委托': '📜'
        };
        return icons[type] || '📜';
    }

    function getTypeClass(type) {
        var classes = {
            '主线': 'main',
            '支线': 'side',
            '日常': 'daily',
            '紧急': 'urgent',
            '委托': 'side'
        };
        return classes[type] || 'side';
    }

    function renderStars(count, max) {
        var html = '';
        for(var i = 0; i < max; i++) {
            if(i < count) html += '★';
            else html += '<span class="empty">☆</span>';
        }
        return html;
    }

    function renderQuest(data) {
        if(!data.title) return '<div class="empty-state">等待任务数据...</div>';

        var html = '<div class="quest-header">';
        html += '<div class="quest-icon">' + getQuestIcon(data.type) + '</div>';
        html += '<span class="quest-type-badge ' + getTypeClass(data.type) + '">' + escapeHtml(data.type) + '</span>';
        html += '<div class="quest-title">' + escapeHtml(data.title) + '</div>';
        html += '</div>';

        // 信息网格
        html += '<div class="quest-info-grid">';

        if(data.difficulty) {
            html += '<div class="info-card"><div class="info-label">⚔ 难度</div>';
            html += '<div class="info-value"><span class="difficulty-stars">' + renderStars(data.difficultyStars, 5) + '</span>';
            // 提取括号内的说明
            var diffNote = data.difficulty.replace(/[★☆]+/g, '').replace(/[（(\[\])）]/g, '').trim();
            if(diffNote) html += ' <span style="font-size:11px;color:var(--ink-faded);">' + escapeHtml(diffNote) + '</span>';
            html += '</div></div>';
        }

        if(data.reward) {
            html += '<div class="info-card"><div class="info-label">💰 报酬</div>';
            html += '<div class="info-value">' + escapeHtml(data.reward) + '</div></div>';
        }

        html += '</div>';

        // 详情
        if(data.detail) {
            html += '<div class="quest-detail-section"><div class="section-title">任务详情</div>';
            html += '<div class="detail-content">' + escapeHtml(data.detail) + '</div></div>';
        }

        // 发布者
        if(data.publisher) {
            html += '<div class="publisher-section">';
            html += '<div class="publisher-icon">👤</div>';
            html += '<div class="publisher-info">';
            html += '<div class="publisher-label">任务发布者</div>';
            html += '<div class="publisher-name">' + escapeHtml(data.publisher) + '</div>';
            html += '</div></div>';
        }

        return html;
    }

    function initQuest() {
        var container = document.getElementById('questContent');
        var raw = extractRawQuest();

        if(!raw || !raw.trim()) {
            container.innerHTML = '<div class="empty-state">等待任务数据...</div>';
            return;
        }

        var parsed = parseQuestContent(raw);
        container.innerHTML = renderQuest(parsed);
        updateHeight();
    }

    if(document.readyState === 'complete' || document.readyState === 'interactive') setTimeout(initQuest, 0);
    document.addEventListener('DOMContentLoaded', initQuest);
    setTimeout(initQuest, 100);
    setTimeout(initQuest, 300);
})();
</script>
</body>
</html>
